import{_ as o,o as d,c,ai as t}from"./chunks/framework.Ba-VnP44.js";const E=JSON.parse('{"title":"ERP 企业资源计划 · OpenBiz 第五个独立消费者","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/erp.md","filePath":"apps/openbiz/erp.md"}'),r={name:"apps/openbiz/erp.md"};function a(i,e,n,s,p,l){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="erp-企业资源计划-·-openbiz-第五个独立消费者" tabindex="-1">ERP 企业资源计划 · OpenBiz 第五个独立消费者 <a class="header-anchor" href="#erp-企业资源计划-·-openbiz-第五个独立消费者" aria-label="Permalink to “ERP 企业资源计划 · OpenBiz 第五个独立消费者”">​</a></h1><blockquote><p>现为独立应用 <code>openbiz-erp-app</code>（<code>E:/8.cangku/for-job/openbiz-erp-app</code>）：独立后端（端口 18085）+ 独立前端（Vue3/TS）+ 独立数据库 <code>openbiz_erp</code>。</p></blockquote><blockquote><p>实证：OpenBiz shop 域有 Inventory CAS、business 域有 Order，但采购 / 供应商需自建。按 OpenBiz 命名约定自建 <code>openbiz_erp_*</code> 表，在其多租户基座之上实现「物料 → 供应商 → 采购单 → 收货入库 → 库存台账」的完整采购域闭环。验证「百套流水线」对 A 类工程量最大系统（第 3 个）的可复制性。</p></blockquote><h2 id="复用与自建" tabindex="-1">复用与自建 <a class="header-anchor" href="#复用与自建" aria-label="Permalink to “复用与自建”">​</a></h2><ul><li><strong>复用</strong>：OpenBiz <code>openbiz-saas-core</code> 多租户、<code>ruoyi-framework</code> 基础能力（用户 / 角色 / token）</li><li><strong>自建</strong>：6 张 <code>openbiz_erp_*</code> 业务表 + 1 张单号计数器表 + Mapper / Service / Controller + 元数据驱动前端 <ul><li>供应商状态机：<code>ACTIVE ⇄ FROZEN</code>，二者均可 <code>→ BLOCKED</code>（终态）；BLOCKED 解冻被拒</li><li>采购单状态机：<code>DRAFT → SUBMITTED → APPROVED → ORDERED → RECEIVED</code>（终态）；<code>CANCELLED</code> 仅 DRAFT/SUBMITTED 可转</li><li>物料状态：<code>ACTIVE ⇄ DISABLED</code>（极简两态，不引入状态机）</li><li>统计：<code>GET /api/erp/orders/stats</code> 返回 status 全态 + stage（PLANNING/EXECUTING/CLOSED）双维度，缺段补 0</li></ul></li></ul><h2 id="数据模型-6-张业务表-1-张计数器表" tabindex="-1">数据模型（6 张业务表 + 1 张计数器表） <a class="header-anchor" href="#数据模型-6-张业务表-1-张计数器表" aria-label="Permalink to “数据模型（6 张业务表 + 1 张计数器表）”">​</a></h2><table tabindex="0"><thead><tr><th>表</th><th>关键字段</th><th>说明</th></tr></thead><tbody><tr><td><code>openbiz_erp_material</code></td><td><code>material_code</code> · <code>name</code> · <code>spec</code> · <code>unit</code> · <code>purchase_price</code> · <code>wms_sku_code</code> · <code>status</code></td><td><code>uk(tenant_id, material_code)</code>；<code>wms_sku_code</code> 对齐 WMS 的 <code>sku_code</code></td></tr><tr><td><code>openbiz_erp_supplier</code></td><td><code>name</code> · <code>contact</code> · <code>phone</code> · <code>grade</code> · <code>status</code></td><td><code>uk(tenant_id, name)</code>；<code>status</code> ∈ ACTIVE/FROZEN/BLOCKED</td></tr><tr><td><code>openbiz_erp_purchase_order</code></td><td><code>order_no</code> · <code>supplier_id</code> · <code>total_amount</code> · <code>stage</code> · <code>status</code> · <code>submit_by</code> · <code>approve_by</code> · <code>version</code></td><td><code>uk(tenant_id, order_no)</code>；<code>stage</code> 由 status 推导；<code>version</code> 为乐观锁版本号</td></tr><tr><td><code>openbiz_erp_purchase_order_item</code></td><td><code>order_id</code> · <code>material_code</code> · <code>qty</code> · <code>unit_price</code> · <code>tax_rate</code> · <code>tax_amount</code> · <code>amount</code></td><td>金额全部服务端推导</td></tr><tr><td><code>openbiz_erp_inventory</code></td><td><code>warehouse_code</code> · <code>material_code</code> · <code>qty</code> · <code>avg_cost</code> · <code>version</code></td><td><code>uk(tenant_id, warehouse, material)</code>；移动加权平均成本</td></tr><tr><td><code>openbiz_erp_stock_txn</code></td><td><code>txn_no</code> · <code>direction</code> · <code>qty</code> · <code>biz_type</code> · <code>source_doc_no</code> · <code>create_by</code></td><td>只增不改的账本；<code>uk(tenant_id, source_doc_no, material, direction)</code> 做幂等</td></tr><tr><td><code>openbiz_erp_order_seq</code></td><td><code>tenant_id</code> · <code>seq_date</code> · <code>seq</code></td><td>单号计数器（非业务表）；<code>pk(tenant_id, seq_date)</code>，原子分配 <code>PO-yyyyMMdd-NNNN</code></td></tr></tbody></table><h2 id="业务闭环-e2e-已验证" tabindex="-1">业务闭环（E2E 已验证） <a class="header-anchor" href="#业务闭环-e2e-已验证" aria-label="Permalink to “业务闭环（E2E 已验证）”">​</a></h2><p>登录 → 建物料 → 建供应商(ACTIVE) → 冻结/解冻闭环 → 建采购单(2 行明细，合计服务端推导) → 提交 → 审批 → 下单 → <strong>收货(RECEIVED，同事务自动入库并写流水)</strong> → 库存台账增加、流水可按单号反查 → 重复收货被状态机拦 → 超量出库被拒 → 冻结供应商下单被拒 → 数据落库可重拉。</p><p>账本侧闭环（1.7 补测）：查流水（全量数组，按 <code>materialCode</code> / <code>sourceDocNo</code> 过滤）→ 手工入库 → 手工出库 → 超量出库 409 → <strong>账实相符断言</strong>（台账结存 == 该物料全部流水净累计）→ 非法参数 400。</p><p>单测 <strong>125 条</strong>（<code>mvn -o test</code>，1.3s，不连库）+ E2E <strong>259 条</strong>（域链路 94 + 统一契约 100 + 并发 36 + 账本契约 29），全部通过。</p><h2 id="工程约束-p0-p1-补强" tabindex="-1">工程约束（P0 / P1 补强） <a class="header-anchor" href="#工程约束-p0-p1-补强" aria-label="Permalink to “工程约束（P0 / P1 补强）”">​</a></h2><ul><li><strong>强类型 DTO + Bean Validation</strong>：入参不再用 <code>Map&lt;String,Object&gt;</code>，改为 <code>dto/ErpRequests</code> + <code>@Valid</code>，校验失败 400 且压成「字段: 原因」。</li><li><strong>三类错误分层</strong>：400 参数错 / 403 越权（<code>ErpForbiddenException</code>）/ 409 状态机与业务规则冲突，客户端能据此决定「改参数、去申请授权、还是重读状态」。</li><li><strong>业务权限 + 职责分离</strong>：<code>erp_buyer</code> / <code>erp_approver</code> / <code>erp_warehouse</code> / <code>erp_manager</code> 四角色映射 12 个权限点；<code>submit_by ≠ approve_by</code>，自审 409 <code>SELF_APPROVAL_FORBIDDEN</code>。</li><li><strong>库存正确性靠数据库</strong>：入库 <code>ON DUPLICATE KEY UPDATE</code> 原子加权，出库 <code>WHERE qty &gt;= ?</code> 杜绝负库存，幂等靠唯一键而非应用判重。</li><li><strong>两层并发控制</strong>：状态流转用 CAS（<code>WHERE status = 旧值</code>），业务字段编辑用乐观锁（<code>WHERE version = ?</code>）；两者冲突都归 409 <code>CONCURRENT_MODIFICATION</code>，但文案可区分「当前状态」与「版本已失效」。</li><li><strong>列表过滤与排序下沉 SQL</strong>：<code>keyword</code> / <code>status</code> / 关联对象过滤 + 白名单排序，<code>count</code> 与 <code>page</code> 共用同一 where 片段；排序列名不在白名单直接拒绝，不拼进 SQL。</li><li><strong>软删 + 审计</strong>：六张业务表均有 <code>deleted</code> / <code>create_by</code>，采购单另有 <code>submit_by</code> / <code>approve_by</code> / <code>version</code>。</li><li><strong>业务单号</strong>：<code>PO-yyyyMMdd-NNNN</code>，由数据库单行计数器原子分配（<code>LAST_INSERT_ID(seq+1)</code>），6 线程并发建单不重号；库存流水 <code>source_doc_no</code> 记的就是它。</li></ul><h2 id="工程位置" tabindex="-1">工程位置 <a class="header-anchor" href="#工程位置" aria-label="Permalink to “工程位置”">​</a></h2><p><code>E:/8.cangku/for-job/openbiz-erp-app</code>（端口 18085，含 README、5 个迁移脚本与 4 套 E2E 脚本（域链路 / 统一契约 / 并发 / 账本契约））</p><h2 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h2><p>工程量最大的 A 类系统（主数据 / 单据链 / 单据-库存联动 / 角色权限）同样可在 OpenBiz 基座上以独立消费者方式落地。相较前四个应用，ERP 多证明了两件事：</p><ol><li><strong>底座能撑住「跨模块事务一致性」</strong>——收货 = 状态流转 + 流水 + 台账，三者在同一事务内，不靠最终一致兜底；</li><li><strong>底座能撑住「业务级权限」</strong>——RuoYi 的菜单权限对本应用是空转的，改用 <code>sys_role.role_key</code> 映射业务权限点，说明基座的用户体系可被复用而不被其权限模型绑死。</li></ol><h2 id="下一步-规划-未实现" tabindex="-1">下一步（规划，未实现） <a class="header-anchor" href="#下一步-规划-未实现" aria-label="Permalink to “下一步（规划，未实现）”">​</a></h2><p>当前是「采购域闭环 + 库存入账」，不是完整进销存，更不是可交付商用的 ERP。P2 / P3 待补：</p><ul><li>[ ] <strong>销售管理</strong>：客户 / 报价 / 销售订单 / 发货（出库走同一账本，<code>biz_type=SALES_DELIVERY</code> 已预留）</li><li>[ ] <strong>应收应付台账</strong>：收货生成 AP、发货生成 AR（业财一体的最小一步）</li><li>[ ] <strong>Excel 导出 / 单据打印</strong>：中小企业对账与报税的刚需，成本最低、优先级不低</li><li>[ ] <strong>多级可配置审批流</strong>：当前 <code>submit → approve</code> 单级硬编码，无审批人 / 流程表</li><li>[ ] <strong>采购申请 → 订单闭环、采购退货、三单匹配</strong>（订单-收货-发票）</li><li>[ ] <strong>多仓 / 批次 / FIFO、盘点单、库存预警</strong>（当前单仓硬编码 <code>MAIN</code>，成本为移动加权）</li><li>[x] <strong>并发与分页</strong>（1.5）：分页下沉到 SQL、状态流转 CAS、6 线程收货/提交/建单/出库实测</li><li>[x] <strong>业务字段乐观锁 + 列表过滤排序</strong>（1.6）：<code>version</code> 列乐观锁、keyword/status/关联对象过滤 + 白名单排序、出入库写序统一、并发编辑实测</li><li>[x] <strong>前端补齐库存流水台账 + 手工出入库入口</strong>（1.7）：新增第 5 个实体「库存流水」与手工出入库对话框，后端 1.4 就有的账本能力终于能在界面上演示；新增 <code>e2e_ledger.py</code> 29 条断言（含账实相符）</li><li>[ ] <strong>工程补课（剩余）</strong>：字段级审计表（记录改了哪一列的前后值）、压测工具（k6 / JMeter）跑吞吐与长稳</li><li>[ ] <strong>与 WMS / MES 打通</strong>：模型与契约已对齐（WMS <code>inboundType</code> 默认已是 <code>PURCHASE</code>），但 ERP 侧尚无集成层（无 HTTP client / MQ / 事件发布），属架构孤点</li></ul><p>明确不在此页范围：财务总账、多组织合并报表、与第三方 ERP（如 SAP / 用友）的对接——这些超出 OpenBiz 作品集定位，属企业真实深水区。</p><p>详细架构、接口契约、状态机完整迁移表、权限矩阵与「单测 125 + E2E 259」验收清单见 <a href="/my-vitepress-site/instances/business/erp.html">ERP 实例页</a>。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 试水实证</a></p>',25)])])}const g=o(r,[["render",a]]);export{E as __pageData,g as default};
